const property = items[0].json;
const formatted = {
  title: property.title,
  description: property.description,
  price: property.price,
  location: property.location,
  specs: property.specs,
  images: property.images,
  features: property.features,
  listingType: property.listingType,
  agent: property.agent,
};

items.json = [{ formatted }];
return items;

const formatted = items.json[0];
const pageId = $const('FACEBOOK_PAGE_ID');
const accessToken = $const('FACEBOOK_ACCESS_TOKEN');

if (!pageId || !accessToken) {
  throw new Error('Facebook Page ID or Access Token not configured');
}

const mediaUrl = formatted.images[0];

const mediaResponse = await fetch(`https://graph.facebook.com/v18.0/${pageId}/photos`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    url: mediaUrl,
    caption: formatted.description,
    access_token: accessToken,
  }),
});

if (!mediaResponse.ok) {
  throw new Error('Failed to upload image to Facebook');
}

const mediaData = await mediaResponse.json();

const postResponse = await fetch(`https://graph.facebook.com/v18.0/${pageId}/feed`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    message: formatted.description,
    access_token: accessToken,
  }),
});

if (!postResponse.ok) {
  throw new Error('Failed to post to Facebook');
}

const postData = await postResponse.json();
items.json = [{ postUrl: `https://facebook.com/${pageId}/posts/${postData.id}` }];
return items;

const result = {
  platform: 'facebook',
  success: true,
  postUrl: items.json[0].postUrl,
};
items.json = [result];
return items;

const result = items.json[0];
const webhookUrl = $const('WEBHOOK_URL');

if (webhookUrl) {
  await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ result, platform: 'facebook' }),
  });
}

return items;
